export function roll(formula,random=()=>crypto.getRandomValues(new Uint32Array(1))[0]/4294967296){const m=String(formula).replace(/\s/g,'').match(/^(\d{1,3})?d(4|6|8|10|12|20|100)([+-]\d{1,4})?$/i);if(!m)throw new Error('Формат: 1d20+3, 2d6 или 1d8-1');const count=Number(m[1]||1),sides=Number(m[2]),mod=Number(m[3]||0);if(count<1||count>100)throw new Error('Можно бросить от 1 до 100 кубов');const rolls=Array.from({length:count},()=>Math.floor(random()*sides)+1);return{rolls,total:rolls.reduce((a,b)=>a+b,0)+mod}}
export function initiativeOrder(tokens){return [...tokens].sort((a,b)=>(b.init??-Infinity)-(a.init??-Infinity)||b.mod-a.mod||a.name.localeCompare(b.name,'ru'))}
